create temporary table serviceos_email_diagnostic_function_permissions on commit drop as select jsonb_agg(x-'definition' order by x->>'signature') as permissions from jsonb_array_elements((jsonb_build_object('base',jsonb_build_object('base',jsonb_build_object('base',jsonb_build_object('base',jsonb_build_object('base',jsonb_build_object('base',jsonb_build_object('base',jsonb_build_object('base',jsonb_build_object('base',jsonb_build_object('base',jsonb_build_object('base',jsonb_build_object('base',jsonb_build_object('base',jsonb_build_object('base',jsonb_build_object('base',jsonb_build_object('delivery',jsonb_build_object('health',jsonb_build_object(
 'runtime',jsonb_build_object(
