 'indexes',(select jsonb_agg(indexdef order by indexname) from pg_indexes where schemaname='public' and tablename=c.relname)) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname='org_units')),'functions',(select coalesce(jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'definition',(case when p.oid='public.learn_performance_correct(uuid,uuid,uuid,integer,numeric,text)'::regprocedure then replace((case when p.oid in ('email_ingestion_payload_v2(text,text,jsonb)'::regprocedure,'learn_email_job_fail(uuid,uuid,uuid,text,integer)'::regprocedure,'learn_operator_capture_health(uuid,text)'::regprocedure) then '[definition checked separately]' else pg_get_functiondef(p.oid) end),$recovery_patch$ if exists(select 1 from public.learn_correction_cancellations where id=p_request) then
  raise exception 'Correction request cancelled; review evidence before a new correction' using errcode='PT409';end if;
