$recovery_patch$,'') else (case when p.oid in ('email_ingestion_payload_v2(text,text,jsonb)'::regprocedure,'learn_email_job_fail(uuid,uuid,uuid,text,integer)'::regprocedure,'learn_operator_capture_health(uuid,text)'::regprocedure) then '[definition checked separately]' else pg_get_functiondef(p.oid) end) end),'owner',pg_get_userbyid(p.proowner),'acl',p.proacl::text) order by p.oid::regprocedure::text),'[]') from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('learn_work_measurement_receipt_check','learn_measurement_receipt_constraint','learn_review_receipt_constraint','learn_assessment_receipt_constraint')),
 'triggers',(select coalesce(jsonb_agg(jsonb_build_object('table',c.relname,'name',t.tgname,'definition',pg_get_triggerdef(t.oid),'enabled',t.tgenabled,'deferrable',t.tgdeferrable,'initiallyDeferred',t.tginitdeferred) order by c.relname,t.tgname),'[]') from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and t.tgname in ('learn_measurement_receipt_guard','learn_review_receipt_guard','learn_assessment_receipt_guard')),
 'constraints',(select coalesce(jsonb_agg(jsonb_build_object('table',c.relname,'name',x.conname,'definition',pg_get_constraintdef(x.oid),'type',x.contype,'deferrable',x.condeferrable,'initiallyDeferred',x.condeferred) order by c.relname,x.conname),'[]') from pg_constraint x join pg_class c on c.oid=x.conrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and x.conname in ('learn_measurement_receipt_guard','learn_review_receipt_guard','learn_assessment_receipt_guard')),
