-- Preserve allowlisted Workspace diagnostics through the existing durable protocol.
-- No source rows, authority, function owners or grants are changed.
CREATE OR REPLACE FUNCTION public.email_ingestion_payload_v2(op text, stream text, v jsonb)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
declare names text[]; t jsonb; k text;
begin
  case op
  when 'claim' then
    names:=array['recovery'];
    if stream='recent' and v ? 'force' then
      names:=names||array['force'];
      if jsonb_typeof(v->'force') is distinct from 'boolean' then raise exception using errcode='22023',message='invalid_force'; end if;
    end if;
    perform public.email_ingestion_keys_v2(v,names);
    if v->'recovery'<>'null'::jsonb then perform public.email_ingestion_recovery_v2(v->'recovery'); end if;
  when 'initialize_traversal' then
    perform public.email_ingestion_keys_v2(v,array['captured_history_id','captured_at','page_size','query']);
    if stream<>'recent' or jsonb_typeof(v->'captured_history_id') is distinct from 'string' or
      not coalesce(v->>'captured_history_id'~'^(0|[1-9][0-9]{0,19})$',false) then raise exception using errcode='22023',message='invalid_boundary'; end if;
    if (v->>'captured_history_id')::numeric>18446744073709551615 or v->'query'<>'null'::jsonb or
      not public.email_ingestion_count_v2(v->'page_size') or (v->>'page_size')::integer not between 1 and 500 or
      not coalesce(v->>'captured_at'~'^\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d\.\d{3}Z$',false) then raise exception using errcode='22023',message='invalid_boundary'; end if;
    perform (v->>'captured_at')::timestamptz;
  when 'checkpoint' then
    names:=array['returned_next_page_token','exhausted','page_evidence','yield_after_page'];
    if stream='recent' then names:=names||array['label','expected_input_page_token'];
    else names:=names||array['expected_page_token','expected_total','listed_count']; end if;
    perform public.email_ingestion_keys_v2(v,names);
    perform public.email_ingestion_evidence_v2(v->'page_evidence','success');
    if stream='recent' then
      if not coalesce(v->>'label'=any(array['INBOX','SENT']),false) then raise exception using errcode='22023',message='invalid_page'; end if;
      k:='expected_input_page_token';
    else
      k:='expected_page_token';
      if not public.email_ingestion_count_v2(v->'expected_total') or not public.email_ingestion_count_v2(v->'listed_count') then raise exception using errcode='22023',message='invalid_page'; end if;
    end if;
    foreach t in array array[v->k,v->'returned_next_page_token'] loop
      if t<>'null'::jsonb and (jsonb_typeof(t)<>'string' or length(t#>>'{}') not between 1 and 8192) then raise exception using errcode='22023',message='invalid_token'; end if;
    end loop;
    if jsonb_typeof(v->'exhausted')<>'boolean' or jsonb_typeof(v->'yield_after_page')<>'boolean' or
      (v->>'exhausted')::boolean is distinct from (v->'returned_next_page_token'='null'::jsonb) then raise exception using errcode='22023',message='invalid_page'; end if;
  when 'release' then
    perform public.email_ingestion_keys_v2(v,array['reason_code','attempt_evidence']);
    if not coalesce(v->>'reason_code'=any(array['page_budget','time_budget','requested_yield']),false) then raise exception using errcode='22023',message='invalid_release'; end if;
    perform public.email_ingestion_evidence_v2(v->'attempt_evidence','release');
  when 'block','finish_attempt' then
    names:=array['error_code','attempt_evidence'];
    if op='finish_attempt' then names:=names||array['outcome'];
      if not coalesce(v->>'outcome'=any(array['failed','superseded']),false) then raise exception using errcode='22023',message='invalid_outcome'; end if;
    end if;
    perform public.email_ingestion_keys_v2(v,names);
    if not coalesce(v->>'error_code'=any(array['history_expired','continuation_expired','pagination_no_progress','fetch_failed','parse_failed','persistence_failed','checkpoint_conflict','source_ineligible','unexpected_failure','sa_config_missing','sa_credentials_invalid','admin_delegation_missing','scopes_missing','delegation_grant_invalid','delegation_denied']),false) then raise exception using errcode='22023',message='invalid_error'; end if;
    perform public.email_ingestion_evidence_v2(v->'attempt_evidence','failure');
  when 'takeover' then
    perform public.email_ingestion_keys_v2(v,array['recovery']); perform public.email_ingestion_recovery_v2(v->'recovery');
  when 'restart' then
    names:=array['reason_code','recovery'];
    if stream='recent' and v ? 'fetch_policy' then
      names:=names||array['fetch_policy'];
      if not coalesce(v->>'fetch_policy'=any(array['missing_only','refetch_all']),false) then raise exception using errcode='22023',message='invalid_fetch_policy'; end if;
    end if;
    perform public.email_ingestion_keys_v2(v,names); perform public.email_ingestion_recovery_v2(v->'recovery');
    if not coalesce(v->>'reason_code'=any(array['operator_restart','history_expired','continuation_expired']),false) then raise exception using errcode='22023',message='invalid_restart'; end if;
  else raise exception using errcode='22023',message='invalid_operation';
  end case;
end $function$
;
create or replace function public.learn_email_job_fail(p_tenant uuid,p_job uuid,p_attempt uuid,p_claimed_by text,p_claim integer) returns jsonb
language plpgsql security invoker set search_path=pg_catalog as $$
declare j public.platform_jobs%rowtype;b public.learn_email_job_attempts%rowtype;r public.email_sync_runs%rowtype;receipt jsonb;code text;answer jsonb;begin
 if current_user<>'service_role' then raise exception 'learn_email_job_forbidden' using errcode='42501';end if;
 if p_tenant is null or p_job is null or p_attempt is null or nullif(p_claimed_by,'') is null or p_claim is null or p_claim<1 then raise exception 'learn_email_job_invalid' using errcode='22023';end if;
 select * into j from public.platform_jobs where tenant_id=p_tenant and id=p_job for update;
 if not found then raise exception 'learn_email_job_not_owned' using errcode='PT409';end if;
 receipt:=j.metadata->'learn_email_failure_v1';
 if j.status='dead_letter' and j.claimed_by=p_claimed_by and j.attempt_count=p_claim
  and receipt->>'attempt_id'=p_attempt::text and receipt->>'claimed_by'=p_claimed_by and receipt->>'claim'=p_claim::text
  and receipt->>'version'='learn-email-job-failure/1' then return receipt->'answer'||jsonb_build_object('disposition','replayed');end if;
 select * into b from public.learn_email_job_attempts where job_id=p_job and tenant_id=p_tenant and attempt_id=p_attempt;
 if not found then raise exception 'learn_email_job_binding_missing' using errcode='PT409';end if;
 perform public.learn_email_attempt_lease(p_attempt,p_claimed_by,p_claim);
 select * into r from public.email_sync_runs where id=b.attempt_id and tenant_id=b.tenant_id for key share;
 if not found or r.provider<>'gmail' or r.sync_type<>b.sync_type or r.status<>'failed' or r.completed_at is null
  or (r.metadata->>'email_account_id')::uuid is distinct from b.email_account_id then raise exception 'learn_email_attempt_not_failed' using errcode='PT409';end if;
 code:=case when r.error_message=any(array['history_expired','continuation_expired','pagination_no_progress','fetch_failed','parse_failed','persistence_failed','checkpoint_conflict','source_ineligible','unexpected_failure','sa_config_missing','sa_credentials_invalid','admin_delegation_missing','scopes_missing','delegation_grant_invalid','delegation_denied']) then r.error_message else 'capture_failed' end;
 answer:=jsonb_build_object('version','learn-email-job-failure/1','disposition','applied','job_id',j.id,'attempt_id',r.id,'code',code);
 receipt:=jsonb_build_object('version','learn-email-job-failure/1','attempt_id',r.id,'claimed_by',p_claimed_by,'claim',p_claim,'answer',answer);
 update public.platform_jobs set status='dead_letter',completed_at=clock_timestamp(),lease_expires_at=null,error_code=code,
  result=jsonb_build_object('sync_run_id',r.id,'error_code',code),metadata=coalesce(metadata,'{}')||jsonb_build_object('learn_email_failure_v1',receipt) where id=j.id;
 if j.lease_expires_at<=clock_timestamp() then raise exception 'learn_email_job_not_owned' using errcode='PT409';end if;
 return answer;
end $$;

-- Operator-only safe mailbox failure diagnostics; no raw provider errors.
-- Replace the latest health reader without changing its owner or ACL.
create or replace function public.learn_operator_capture_health(p_tenant uuid,p_after text default null)
returns jsonb language plpgsql security definer set search_path=pg_catalog as $$
declare rows jsonb;more boolean;last_key text;begin
 perform public.learn_operator_input_access(p_tenant,auth.uid(),false);
 if p_after is not null and p_after!~'^(email|phone|slack):[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$' then
  raise exception 'learn_operator_health_cursor_invalid' using errcode='22023';end if;
 with candidates as (
  select 'email:'||a.id::text as key,jsonb_build_object(
   'id',a.id,'source','email','provider',case when a.provider='gmail' and a.status in ('active_dwd','pending_tokenless_dwd') then 'google_workspace' when a.provider in ('gmail','google_workspace') then a.provider else 'other_email' end,
   'label',left(coalesce(nullif(a.display_name,''),'Mailbox'),120),
   'enabled',null,'account_state',case when a.status in ('active','active_dwd','pending_tokenless_dwd','disabled','paused','revoked') then a.status else 'unknown' end,
   'auth_state',case when a.status in ('active_dwd','pending_tokenless_dwd') or a.provider='google_workspace' then 'unknown' when a.auth_state in ('ok','expired','revoked','needs_reconnect') then a.auth_state else 'unknown' end,
   'last_success_at',greatest(a.last_incremental_success_at,case when er.status='success' and er.completed_at>=er.started_at then er.completed_at end),
   'last_attempt_at',greatest(a.last_incremental_attempt_at,er.started_at),
   'last_failure_at',greatest(
    case when a.last_sync_error is not null and a.last_incremental_attempt_at>=coalesce(a.last_incremental_success_at,'-infinity') then a.last_incremental_attempt_at end,
    case when er.status='failed' then coalesce(er.completed_at,er.started_at)
     when er.status='success' and (er.completed_at is null or er.completed_at<er.started_at) then er.started_at end),
   'email_failure',case when er.status='failed' then jsonb_build_object('attempt_id',er.id,
    'occurred_at',coalesce(er.completed_at,er.started_at),'code',case when er.error_message=any(array['sa_config_missing','sa_credentials_invalid','admin_delegation_missing','scopes_missing','delegation_grant_invalid','delegation_denied','history_expired','continuation_expired','pagination_no_progress','fetch_failed','parse_failed','persistence_failed','checkpoint_conflict','source_ineligible','unexpected_failure']) then er.error_message else 'capture_failed' end) else null end,
   'latest_job',null,'bounded_complete',null) as row
  from public.email_accounts a
  left join lateral (
   select r.id,r.status,r.started_at,r.completed_at,r.error_message from public.email_sync_runs r
   where a.provider in ('gmail','google_workspace') and r.tenant_id=a.tenant_id
    and r.metadata->>'email_account_id'=a.id::text and r.provider='gmail'
    and r.sync_type in ('messages','workspace_messages')
    and r.sync_type=case when a.provider='google_workspace' or a.status in ('active_dwd','pending_tokenless_dwd') then 'workspace_messages' else 'messages' end
    and r.status in ('success','failed')
   order by r.started_at desc,r.id desc limit 1
  ) er on true
  where a.tenant_id=p_tenant
  union all
  select (case when tc.connector_id='slack' then 'slack:' else 'phone:' end)||a.id::text as key,jsonb_build_object(
   'id',a.id,'source',case when tc.connector_id='slack' then 'slack' else 'phone' end,'provider',tc.connector_id,
   'label',left(coalesce(nullif(a.display_name,''),case when tc.connector_id='slack' then 'Slack channel' else 'Phone account' end),120),
   'enabled',tc.enabled and (case when tc.connector_id='slack' then tc.status='active' else tc.status in ('active','error') end),
   'account_state',case when a.status in ('active','disabled','paused','revoked') then a.status else 'unknown' end,
   'auth_state','unknown','last_success_at',a.last_successful_sync_at,'last_attempt_at',null,'last_failure_at',a.last_failed_sync_at,
   'latest_job',case when j.id is null then null else jsonb_build_object('id',j.id,
    'status',case when j.status in ('queued','running','retrying','succeeded','dead_letter','cancelled') then j.status else 'unknown' end,
    'available_at',j.available_at,'lease_expires_at',j.lease_expires_at,'completed_at',j.completed_at) end,
   'phone_evidence',case when tc.connector_id='simwood' then public.learn_phone_account_evidence(p_tenant,a.id) else null end,
   'bounded_complete',case when tc.connector_id='slack' then coalesce(
    j.status='succeeded' and j.completed_at is not null
    and j.result->>'stopReason'='window_pages_complete'
    and j.result->'complete'='true'::jsonb and a.sync_cursor->'complete'='true'::jsonb
    and jsonb_typeof(a.sync_cursor->'scopeKey')='string' and a.sync_cursor->>'scopeKey'<>''
    and j.result->'scopeKey'=a.sync_cursor->'scopeKey'
    and j.result->'pages'=a.sync_cursor->'pages',false) else null end) as row
  from public.connector_accounts a join public.tenant_connectors tc on tc.id=a.tenant_connector_id and tc.tenant_id=a.tenant_id
  left join lateral(select q.id,q.status,q.available_at,q.lease_expires_at,q.completed_at,q.result from public.platform_jobs q
   where tc.connector_id='slack' and q.tenant_id=p_tenant and q.job_type='slack.history_sync' and q.payload->>'connector_account_id'=a.id::text
   order by q.created_at desc,q.id desc limit 1) j on true
  where a.tenant_id=p_tenant and ((tc.connector_id='simwood' and tc.provider='simwood') or (tc.connector_id='slack' and tc.provider='slack'))
 ), bounded as (select * from candidates where p_after is null or key>p_after order by key limit 51), page as (select * from bounded order by key limit 50)
 select coalesce((select jsonb_agg(row||jsonb_build_object('key',key) order by key) from page),'[]'),
  (select count(*)>50 from bounded),(select key from page order by key desc limit 1) into rows,more,last_key;
 return jsonb_build_object('version','learn-operator-capture-health/1','tenant_id',p_tenant,'checked_at',clock_timestamp(),'phone_processing',public.learn_phone_processing_evidence(p_tenant),'rows',rows,'next_cursor',case when more then last_key else null end);
end $$;

savepoint email_diagnostic_probe;
-- Rollback probe: existing functions only, no identities, grants or provider work.
do $probe$declare code text;role_name text;denied boolean;evidence jsonb;begin
 evidence:=jsonb_build_object('persistence','confirmed','message_upsert_count',0,'thread_upsert_count',0,'ids_seen',0,'gone_count',0,'unresolved_count',1,'classification','source_ineligible','coverage_complete',false);
 foreach code in array array['sa_config_missing','sa_credentials_invalid','admin_delegation_missing','scopes_missing','delegation_grant_invalid','delegation_denied'] loop
  perform public.email_ingestion_payload_v2('block','recent',jsonb_build_object('error_code',code,'attempt_evidence',evidence));
  perform public.email_ingestion_payload_v2('finish_attempt','historical',jsonb_build_object('error_code',code,'attempt_evidence',evidence,'outcome','failed'));
 end loop;
 denied:=false;
 begin perform public.email_ingestion_payload_v2('block','recent',jsonb_build_object('error_code','PRIVATE_UNKNOWN_PROVIDER_RESPONSE','attempt_evidence',evidence));exception when invalid_parameter_value then denied:=true;end;
 if not denied then raise exception 'Unknown provider diagnostic accepted';end if;
 perform set_config('request.jwt.claim.sub','',true);perform set_config('request.jwt.claims','{}',true);
 foreach role_name in array array['anon','authenticated','service_role'] loop
  execute 'set local role '||quote_ident(role_name);
  denied:=false;
  begin perform public.learn_operator_capture_health(gen_random_uuid());exception when insufficient_privilege then denied:=true;end;
  if not denied then raise exception 'Actorless operator read admitted';end if;
  if role_name<>'service_role' then
   denied:=false;
   begin perform public.learn_email_job_fail(gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),'diagnostic-probe',1);exception when insufficient_privilege then denied:=true;end;
   if not denied then raise exception 'Client failure settlement admitted';end if;
  end if;
  execute 'reset role';
 end loop;
end $probe$;

rollback to savepoint email_diagnostic_probe;
